'use strict';
const customerMasterForm=Business.masterForm.bind(Business);
Business.masterForm=async function(type,row={}){
 if(type!=='customers')return customerMasterForm(type,row);const d=await this.load();
 this.open(row.id?'编辑客户档案':'新增客户',`<form id="customer-form" class="user-form"><div class="form-grid"><label>客户名称<input name="name" required maxlength="160" value="${esc(row.name||'')}"></label><label>客户代码<input name="code" required maxlength="60" value="${esc(row.code||'')}"></label><label>项目<select name="project_id" ${row.id?'disabled':''}>${this.options(d.projects,row.project_id,'name')}</select></label><label>邮件<input type="email" name="email" maxlength="320" value="${esc(row.email||'')}"></label><label>联系电话<input type="tel" name="phone" maxlength="80" value="${esc(row.phone||'')}"></label><label>状态<select name="active"><option value="true">启用</option><option value="false" ${row.active===false?'selected':''}>停用</option></select></label></div><label>地址<textarea name="address" maxlength="1000">${esc(row.address||'')}</textarea></label><p>客户名称、地址、邮件及联系电话将自动用于 Packing List。</p><p class="error" id="customer-error" role="alert"></p><button class="button primary">保存客户</button><a class="button secondary" href="/customers">返回客户管理</a></form>`);
 $('customer-form').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;try{const body=Object.fromEntries(new FormData(e.target));body.active=body.active==='true';if(row.id)body.version=row.version;await API.request('/masters/customers'+(row.id?'/'+row.id:''),{method:row.id?'PATCH':'POST',body});await Router.go('/customers');notify('客户已保存');}catch(err){$('customer-error').textContent=err.message;e.submitter.disabled=false;}};
};
const Dispatch={
 mappingPanel(p,current,change){p.sheets=p.sheets||[current?.sheet].filter(Boolean);const m=current||{sheet:p.sheets[0],header_row:1,truck_column:1,trailer_column:2,capacity_column:null,capacity_kg:false};$('dispatch-mapping').innerHTML=`<details class="lp-load-summary" ${current?'':'open'}><summary>调整识别列</summary><div class="form-grid"><label>工作表<select id="dispatch-sheet">${p.sheets.map(s=>'<option '+(m.sheet===s?'selected':'')+'>'+esc(s)+'</option>').join('')}</select></label><label>表头行号<input id="dispatch-header" type="number" min="1" max="60" value="${m.header_row}"></label><label>车头列号（A=1）<input id="dispatch-truck" type="number" min="1" max="256" value="${m.truck_column}"></label><label>拖车列号（A=1）<input id="dispatch-trailer" type="number" min="1" max="256" value="${m.trailer_column}"></label><label>载重列号（选填，A=1）<input id="dispatch-capacity" type="number" min="1" max="256" value="${m.capacity_column||''}"></label><label>载重单位<select id="dispatch-unit"><option value="t">吨</option><option value="kg" ${m.capacity_kg?'selected':''}>kg</option></select></label></div><p>修改识别列后，请再次读取预览。</p></details>`;const update=()=>change({sheet:$('dispatch-sheet').value,header_row:Number($('dispatch-header').value),truck_column:Number($('dispatch-truck').value),trailer_column:Number($('dispatch-trailer').value),capacity_column:$('dispatch-capacity').value?Number($('dispatch-capacity').value):null,capacity_kg:$('dispatch-unit').value==='kg'});$('dispatch-mapping').onchange=update;if(!current)update();},
 table(rows){return `<div class="business-table"><table><thead><tr><th>Excel行号</th><th>车头号</th><th>拖车号</th><th>载重（吨）</th><th>识别结果</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${r.source_row}</td><td data-no-i18n>${esc(r.truck_no)}</td><td data-no-i18n>${esc(r.trailer_no||'—')}</td><td>${r.capacity_tonnes?Tonnes.format(r.capacity_tonnes):'未提供'}</td><td>${r.cancelled_at||r.cancelled?'已取消 · 不计入':r.duplicate||r.counted===false?'重复车辆 · 不计入':'新增 / 已保存'}</td></tr>`).join('')}</tbody></table></div>`;},
 async page(id){const month=new URLSearchParams(location.search).get('shipment_month')||'',d=await API.request('/plans/'+id+'/dispatch'+(month?'?shipment_month='+encodeURIComponent(month):''));Router.page('派车管理',LoadingPlans.context({...d.plan,sales_plan_code:d.plan.code})+`<div class="business-toolbar"><a class="button secondary" href="/sales-plans">返回销售管理</a></div><form id="dispatch-month-filter" class="business-toolbar"><label>统计发运月份<input name="shipment_month" type="month" value="${esc(month)}"></label><button class="button secondary">筛选</button><a class="button secondary" href="/sales-plans/${id}/dispatch">全部月份</a></form><div class="shipping-kpis">${[['去重车辆数',d.summary?.vehicle_count||0],['车辆载重合计（吨）',Tonnes.format(d.summary?.total_capacity_tonnes||'0')],['未提供载重车辆',d.summary?.unknown_capacity_count||0]].map(([k,v])=>'<article><span>'+k+'</span><strong>'+v+'</strong></article>').join('')}</div><p>载重合计仅统计已上传的去重车辆，未提供载重的车辆不按零载重推算。同一销售计划、发运月份按车头号去重，重复车辆仅跳过，不覆盖已有记录。</p>${Business.can('dispatch:write')?`<section class="lp-load-summary"><h3>导入客户派车单</h3><form id="dispatch-form" class="user-form"><div class="form-grid"><label>发运月份<input type="month" name="shipment_month" required></label><label>客户Excel派车单<input type="file" name="file" accept=".xls,.xlsx" required></label></div><p>读取车头号、拖车号和车辆载重。新派车单自动跳过重复车辆，仅保存新增车辆；不创建装车单或占用捆包。单次最多2MB、5000辆车。</p><div class="business-toolbar"><button id="dispatch-preview" type="button" class="button secondary">读取预览</button><button id="dispatch-save" class="button primary" disabled>确认保存</button></div><p id="dispatch-error" class="error" role="alert"></p><div id="dispatch-mapping"></div><div id="dispatch-rows"></div></form></section>`:''}<h3>已保存派车单</h3>${d.imports.map(i=>`<details class="lp-load-summary"><summary><strong data-no-i18n>${esc(i.shipment_month)}</strong> · <span data-no-i18n>${esc(i.file_name)}</span> · ${i.row_count} 辆</summary><p data-no-i18n>${esc(i.created_by_name)} · ${esc(new Date(i.created_at).toLocaleString())}</p>${this.table(d.vehicles.filter(v=>v.import_id===i.id))}</details>`).join('')||'<p>暂无派车记录</p>'}`);
 $('dispatch-month-filter').onsubmit=e=>{e.preventDefault();Router.go('/sales-plans/'+id+'/dispatch?'+new URLSearchParams(new FormData(e.target)));};const form=$('dispatch-form');if(!form)return;let fileBody,preview,mapping;const reset=()=>{preview=null;$('dispatch-save').disabled=true;$('dispatch-rows').innerHTML='';};form.elements.shipment_month.onchange=()=>{reset();if(form.elements.file.files.length)$('dispatch-preview').click();};form.elements.file.onchange=()=>{reset();fileBody=null;mapping=null;$('dispatch-mapping').innerHTML='';if(form.elements.shipment_month.value)$('dispatch-preview').click();};
 const read=async()=>{if(!form.elements.shipment_month.value)throw Error('请选择发运月份');const file=form.elements.file.files[0];if(!file)throw Error('请选择客户Excel派车单');if(file.size>2*1024*1024)throw Error('派车单最大2MB');if(!fileBody){const base64=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result.split(',')[1]);r.onerror=()=>reject(Error('文件读取失败'));r.readAsDataURL(file);});fileBody={file_name:file.name,file_base64:base64};}return {...fileBody,shipment_month:form.elements.shipment_month.value,...(mapping?{mapping}: {})};};
 $('dispatch-preview').onclick=async()=>{reset();$('dispatch-preview').disabled=true;$('dispatch-error').textContent='';try{const p=await API.request('/plans/'+id+'/dispatch/import-preview',{method:'POST',body:await read(),timeoutMs:30000});if(p.needs_mapping){this.mappingPanel(p,null,m=>{mapping=m;reset();});return;}preview=p;mapping=p.mapping;this.mappingPanel(p,p.mapping,m=>{mapping=m;reset();});$('dispatch-rows').innerHTML='<p>已读取 '+p.row_count+' 辆，新增 '+p.new_count+' 辆，重复跳过 '+p.duplicate_count+' 辆，请核对后保存。</p>'+(p.warnings?.length?'<p class="dialog-notice">有 '+p.warnings.length+' 行车牌格式需核对，请检查下方预览。</p>':'')+'<p>自动排除取消车辆 '+(p.cancelled_count||0)+' 辆</p>'+this.table([...p.items,...(p.cancelled||[]).map(r=>({...r,cancelled:true}))]);$('dispatch-save').disabled=false;}catch(e){$('dispatch-error').textContent=e.message;}finally{$('dispatch-preview').disabled=false;}};
 form.onsubmit=async e=>{e.preventDefault();if(!preview)return;$('dispatch-save').disabled=true;try{const saved=await API.request('/plans/'+id+'/dispatch',{method:'POST',body:{...await read(),shipment_month:form.elements.shipment_month.value,preview_sha256:preview.file_sha256},timeoutMs:30000});await this.page(id);notify('已新增 '+saved.added_count+' 辆，重复跳过 '+saved.duplicate_count+' 辆');}catch(err){$('dispatch-error').textContent=err.message;$('dispatch-save').disabled=false;}};
 }
};
const salesPermission=Router.permission.bind(Router);Router.permission=p=>/^\/sales-plans\/[0-9a-f-]{36}\/dispatch$/.test(p)?'dispatch:read':salesPermission(p);
const salesInit=Router.init.bind(Router);Router.init=async function(){this.add(/^\/sales-plans\/([0-9a-f-]{36})\/dispatch$/,id=>Dispatch.page(id));const r=await salesInit();for(const nav of document.querySelectorAll('.sidebar nav,.mobile-primary')){const customers=nav.querySelector('[data-primary-route="customers"]'),sales=nav.querySelector('[data-primary-route="sales-plans"]');if(customers&&sales)customers.after(sales);}return r;};
